            {

                using var inStream = new FileStream(files.FullPath, FileMode.Open, FileAccess.Read);

                var srcDoc = formatProvider.Import(inStream, null);

                int startPage = chunkDoc.Pages.Count;

                chunkDoc.Merge(srcDoc);

