        },
        onDoubleClick = { item ->
            // Double click logic here
            // e.g., open edit, navigate, show dialog, etc.
            Toast.makeText(requireContext(), "Double click: ${item.title}", Toast.LENGTH_SHORT).show()
        }
    )
    binding.recyclerView.adapter = adapter
}
```

