```kotlin
override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
    super.onViewCreated(view, savedInstanceState)

    viewModel = ViewModelProvider(requireActivity())[MainActivityViewModel::class.java]

    // 1. recycler needs a LayoutManager
    binding.recyclerPickups.layoutManager =
        androidx.recyclerview.widget.LinearLayoutManager(requireContext())

    // 2. create one adapter instance and keep it
    val cardAdapter = JobCardAdapter(
        onClick = { job -> viewModel.setTaskDetails(job) },
        onDoubleClick = { job ->
            Toast.makeText(requireContext(),"Job#: ${job.JobGuid} is Active",Toast.LENGTH_SHORT).show()
            viewModel.setActiveTask(job)
        }
    )
    binding.recyclerPickups.adapter = cardAdapter

    // collect Flow and push items into adapter
    viewLifecycleOwner.lifecycleScope.launch {
        viewModel.pickupJobs.collect { jobs ->
            cardAdapter.setItems(jobs)
        }
    }
}
```

*No other changes needed—`JobCardAdapter.setItems()` already calls `notifyDataSetChanged()`. Once the `LinearLayoutManager` is set, the cards appear.*

