    }
}

private static string PlainTextToMarkdown(string input)
{
    if (string.IsNullOrWhiteSpace(input)) return string.Empty;

    var lines = input.Replace("\r\n", "\n").Replace('\r', '\n').Split('\n');
    var sb = new StringBuilder(input.Length + 1024);

    bool titleDone = false;
    int consecutiveBlanks = 0;

    var bulletRx   = new Regex(@"^\s*(?:[\u2022\-\*\u00B7]|\d+[.)])\s+"); // • - * · or 1. / 1)
    var underlineRx= new Regex(@"^\s*([=\-])\1{2,}\s*$");                 // === or -- underlines

    for (int i = 0; i < lines.Length; i++)
    {
        var raw = lines[i];
        var line = raw.TrimEnd();

        if (line.Length == 0)
        {
            consecutiveBlanks++;
            if (consecutiveBlanks <= 1) sb.AppendLine();
            continue;
        }
        consecutiveBlanks = 0;

        // Title: first non-empty line, not a bullet/number, reasonably short
        if (!titleDone && line.Length <= 120 && !bulletRx.IsMatch(line))
        {
            // If the next line is ==== or ----, treat as H1; else still H1.
            bool nextIsUnderline = (i + 1 < lines.Length) && underlineRx.IsMatch(lines[i + 1]);
            sb.AppendLine("# " + line.Trim());
            if (nextIsUnderline) i++; // skip underline line
            titleDone = true;
            continue;
        }

        // Heading detection by underline patterns (Markdown style conversion)
        if (i + 1 < lines.Length && underlineRx.IsMatch(lines[i + 1]))
        {
            // Decide H2 vs H3 based on char
            var m = underlineRx.Match(lines[i + 1]);
            var ch = m.Groups[1].Value[0];
            var prefix = (ch == '=') ? "## " : "### ";
            sb.AppendLine(prefix + line.Trim());
            i++; // consume underline
            continue;
        }

        // Bullets / numbered lists
        if (bulletRx.IsMatch(line))
        {
            // Normalize bullets to "- "
            var normalized = bulletRx.Replace(line, "- ");
            sb.AppendLine(normalized.Trim());
            continue;
        }

        // Paragraph line (collapse excessive inner spaces)
        line = Regex.Replace(line, @"[ \t]{2,}", " ");
        sb.AppendLine(line);
    }

    // Collapse 3+ newlines to 2
    var md = Regex.Replace(sb.ToString(), @"(\n){3,}", "\n\n");
    // Trim trailing spaces on lines
    md = Regex.Replace(md, @"[ \t]+$", "", RegexOptions.Multiline);
    return md.Trim() + Environment.NewLine;
}
